public class ExceptionPropagationDemo {
    public static void main(String[] args) {
        try {
            levelOne();
        } catch (IllegalStateException e) {
            System.err.println("Caught at root: " + e.getMessage());
            e.printStackTrace();
        }
    }

    public static void levelOne() {
        levelTwo();
    }

    public static void levelTwo() {
        // Exception propagates up from levelThree, skipping levelTwo's catch blocks
        levelThree();
    }

    public static void levelThree() {
        throw new IllegalStateException("Critical failure propagated from the bottom up.");
    }
}
